import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.collection.factory.impl.DefaultCollectionFactory;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class BindingSetCompatibilityIndexTest {
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void preservesDuplicateRowsAndStreamsWildcardCandidates() throws Exception {
		try (DefaultCollectionFactory factory = new DefaultCollectionFactory();
				BindingSetCompatibilityIndex index = factory.createBindingSetCompatibilityIndex(List.of("x", "y"))) {
			MapBindingSet both = row("both", "a", "b");
			index.add(both);
			index.add(both);
			index.add(row("x-only", "a", null));
			index.add(row("y-only", null, "b"));
			index.add(row("x-conflict-y", "a", "c"));
			index.add(row("x-conflict", "c", "b"));
			index.add(row("empty", null, null));

			MapBindingSet bothBoundProbe = probe("a", "b");
			assertEquals(Map.of("both", 2, "x-only", 1, "y-only", 1, "x-conflict-y", 1, "empty", 1),
					labels(index.candidateRows(bothBoundProbe)));
			assertEquals(Map.of("both", 2, "x-only", 1, "y-only", 1, "empty", 1),
					compatibleLabels(index.candidateRows(bothBoundProbe), bothBoundProbe));
			assertEquals(Map.of("both", 2, "x-only", 1, "y-only", 1, "x-conflict-y", 1, "empty", 1),
					labels(index.candidateRows(probe("a", null))));
			assertEquals(7, count(index.candidateRows(probe(null, null))));
		}
	}

	private static MapBindingSet row(String label, String x, String y) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("label", VF.createLiteral(label));
		if (x != null) {
			row.addBinding("x", VF.createLiteral(x));
		}
		if (y != null) {
			row.addBinding("y", VF.createLiteral(y));
		}
		return row;
	}

	private static MapBindingSet probe(String x, String y) {
		MapBindingSet probe = new MapBindingSet();
		if (x != null) {
			probe.addBinding("x", VF.createLiteral(x));
		}
		if (y != null) {
			probe.addBinding("y", VF.createLiteral(y));
		}
		return probe;
	}

	private static Map<String, Integer> labels(Iterator<BindingSet> rows) {
		Map<String, Integer> labels = new HashMap<>();
		rows.forEachRemaining(row -> {
			labels.merge(row.getValue("label").stringValue(), 1, Integer::sum);
		});
		return labels;
	}

	private static int count(Iterator<BindingSet> rows) {
		int count = 0;
		while (rows.hasNext()) {
			rows.next();
			count++;
		}
		return count;
	}

	private static Map<String, Integer> compatibleLabels(Iterator<BindingSet> rows, BindingSet probe) {
		Map<String, Integer> labels = new HashMap<>();
		while (rows.hasNext()) {
			BindingSet row = rows.next();
			if (compatible(row, probe)) {
				labels.merge(row.getValue("label").stringValue(), 1, Integer::sum);
			}
		}
		return labels;
	}

	private static boolean compatible(BindingSet row, BindingSet probe) {
		for (String name : List.of("x", "y")) {
			if (row.hasBinding(name) && probe.hasBinding(name)
					&& !row.getValue(name).equals(probe.getValue(name))) {
				return false;
			}
		}
		return true;
	}
}
